package dev.zomboid.clans;
import java.util.*;
public final class SurfaceSpawns {
 record Spot(int x,double y,int z){}
 static double support(Object state,Object world,Object pos){Object shape=R.call(state,"getCollisionShape",world,pos);double top=Double.NaN;for(Object box:(List<?>)R.call(shape,"toAabbs")){if(R.num(R.get(box,"minX"))<=.5&&R.num(R.get(box,"maxX"))>=.5&&R.num(R.get(box,"minZ"))<=.5&&R.num(R.get(box,"maxZ"))>=.5){double y=R.num(R.get(box,"maxY"));if(y>0&&(Double.isNaN(top)||y>top))top=y;}}return top;}
 static void refresh(Pve.Wave w,Object nexus){w.surface.clear();Object height=R.get(R.type("net.minecraft.world.level.levelgen.Heightmap$Types"),"MOTION_BLOCKING_NO_LEAVES");int x=(int)R.coord(nexus,"X"),z=(int)R.coord(nexus,"Z");Set<Long> seen=new HashSet<>();for(int i=0;i<192;i++){int radius=i<96?32:48,dx=Pve.random.nextInt(2*radius+1)-radius,dz=Pve.random.nextInt(2*radius+1)-radius;if(Math.max(Math.abs(dx),Math.abs(dz))<8)continue;int px=x+dx,pz=z+dz;long packed=((long)px&0xffffffffL)|((long)pz<<32);if(!seen.add(packed))continue;Object probe=R.make("net.minecraft.core.BlockPos",px,(int)R.coord(nexus,"Y"),pz);if(!R.yes(R.call(w.level,"hasChunkAt",probe)))continue;int y=((Number)R.call(w.level,"getHeight",height,px,pz)).intValue();Object feet=R.make("net.minecraft.core.BlockPos",px,y,pz),floor=R.make("net.minecraft.core.BlockPos",px,y-1,pz);if(!R.yes(R.call(w.level,"canSeeSky",feet)))continue;Object state=R.call(w.level,"getBlockState",floor);double top=support(state,w.level,floor);if(Double.isNaN(top)||!R.yes(R.call(R.call(state,"getFluidState"),"isEmpty"))||!R.yes(R.call(R.call(R.call(w.level,"getBlockState",feet),"getFluidState"),"isEmpty")))continue;w.surface.add(new Spot(px,y-1+top,pz));}if(!w.surface.isEmpty()){double minimum=w.surface.stream().mapToDouble(Spot::y).min().orElse(0);w.surface.removeIf(p->p.y()>minimum+2);}w.nextSurface=Clans.now(R.call(w.level,"getServer"))+100;}
 static void enable(Object mob){R.call(mob,"setNoAi",false);try{Object eval=R.call(R.call(mob,"getNavigation"),"getNodeEvaluator");R.call(eval,"setCanOpenDoors",true);R.call(eval,"setCanPassDoors",true);}catch(Exception unsupported){}}
}
